    correction: [{"quoi":"ما تقوله العبارة","math":"العبارة تدّعي أنّ الزوجية و الفردية تكفيان للأوّلية فيما بينهما"},{"quoi":"نبحث عن مثال مضادّ","math":"نأخذ 10 و هو زوجي، و 15 و هو فردي"},{"quoi":"نفكّك العددين","math":"<span dir=\"ltr\" class=\"expr\">10 = 5 × 2</span> و <span dir=\"ltr\" class=\"expr\">15 = 5 × 3</span>"},{"quoi":"نحسب القاسم المشترك","math":"العدد 5 يقسم 10 و يقسم 15"},{"quoi":"نستنتج","math":"ق.م.أ لهما يقبل القسمة على 5 فهو ليس 1"},{"quoi":"الجواب","math":"خطأ"}],
